application.javascript:
const form = document.getElementById('booking-form');
const list = document.getElementById('booking-list');
const emptyState = document.getElementById('empty-state');
const confirmation = document.getElementById('confirmation');
const message = document.getElementById('form-message');
const count = document.getElementById('booking-count');
const dateInput = document.getElementById('booking-date');

function localDateString() {
  const now = new Date();
  const offset = now.getTimezoneOffset() * 60000;
  return new Date(now.getTime() - offset).toISOString().slice(0, 10);
}
dateInput.min = localDateString();

function updateCount() {
  count.textContent = list.querySelectorAll('[data-status="active"]').length;
  emptyState.hidden = list.querySelectorAll('[data-testid="booking"]').length > 0;
}

function makeBooking(data) {
  const item = document.createElement('article');
  item.className = 'booking-item';
  item.dataset.testid = 'booking';
  item.dataset.status = 'active';

  const top = document.createElement('div');
  top.className = 'booking-top';
  const identity = document.createElement('div');
  const name = document.createElement('div');
  name.className = 'booking-name';
  name.dataset.testid = 'booking-name-display';
  name.textContent = data.name;
  const type = document.createElement('div');
  type.className = 'booking-type';
  type.textContent = data.type;
  identity.append(name, type);
  const cancel = document.createElement('button');
  cancel.type = 'button';
  cancel.className = 'cancel-button';
  cancel.dataset.testid = 'booking-cancel';
  cancel.textContent = 'Cancel';
  top.append(identity, cancel);

  const meta = document.createElement('div');
  meta.className = 'booking-meta';
  const date = document.createElement('span');
  date.textContent = new Date(data.date + 'T00:00:00').toLocaleDateString(undefined, {weekday:'short', month:'short', day:'numeric', year:'numeric'});
  const time = document.createElement('span');
  time.textContent = new Date('1970-01-01T' + data.time).toLocaleTimeString([], {hour:'numeric', minute:'2-digit'});
  const email = document.createElement('span');
  email.textContent = data.email;
  meta.append(date, time, email);
  item.append(top, meta);

  cancel.addEventListener('click', () => {
    item.dataset.status = 'cancelled';
    cancel.remove();
    const label = document.createElement('span');
    label.className = 'cancelled-label';
    label.textContent = 'CANCELLED';
    top.appendChild(label);
    updateCount();
  });
  return item;
}

form.addEventListener('submit', (event) => {
  event.preventDefault();
  message.textContent = '';
  confirmation.hidden = true;
  if (!form.checkValidity()) {
    form.reportValidity();
    return;
  }
  const data = Object.fromEntries(new FormData(form));
  if (data.date < localDateString()) {
    dateInput.setCustomValidity('Please choose today or a future date.');
    dateInput.reportValidity();
    dateInput.setCustomValidity('');
    return;
  }
  list.appendChild(makeBooking(data));
  updateCount();
  confirmation.textContent = 'Booking confirmed for ' + data.name + '.';
  confirmation.hidden = false;
  form.reset();
  dateInput.min = localDateString();
});

updateCount();
